func (b *Builder) ExtractRootfs(options CommitOptions, extractRootfsOptions ExtractRootfsOptions) (io.ReadCloser, chan error, error) {
	src, err := b.makeContainerImageRef(options)
	if err != nil {
		return nil, nil, errors.Wrapf(err, "error creating image reference for container %q to extract its contents", b.ContainerID)
	}
	return src.extractRootfs(extractRootfsOptions)

